class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


